+#!/usr/bin/perl
+use strict;
+use warnings;
+use File::Find;
+use File::Basename;
+
+my $REPO = '/bench/repo';
+my $MODULE = 'github.com/usememos/memos';
+
+# sym_id = "import_path|recv|name"  recv empty for package funcs, *Type for pointer recv
+my (%internal_decls, %all_decls);
+my (%fanin, %fanin_test);          # sym_id -> { caller_id => 1 }
+my (%file_pkg, %file_imports, %file_is_test);
+my (@all_go_files);
+
+sub read_file {
+    my ($path) = @_;
+    open my $fh, '<', $path or die "Cannot read $path: $!";
+    local $/;
+    my $content = <$fh>;
+    close $fh;
+    return $content;
+}
+
+sub strip_go_source {
+    my ($src) = @_;
+    my $out = '';
+    my $i = 0;
+    my $len = length($src);
+    while ($i < $len) {
+        # line comment
+        if (substr($src, $i, 2) eq '//') {
+            while ($i < $len && substr($src, $i, 1) ne "\n") { $i++; }
+            next;
+        }
+        # block comment
+        if (substr($src, $i, 2) eq '/*') {
+            $i += 2;
+            while ($i < $len - 1 && substr($src, $i, 2) ne '*/') { $i++; }
+            $i += 2 if $i < $len;
+            next;
+        }
+        # raw string
+        if (substr($src, $i, 1) eq '`') {
+            $out .= ' ';
+            $i++;
+            while ($i < $len && substr($src, $i, 1) ne '`') { $i++; }
+            $i++ if $i < $len;
+            next;
+        }
+        # double-quoted string
+        if (substr($src, $i, 1) eq '"') {
+            $out .= ' ';
+            $i++;
+            while ($i < $len) {
+                my $c = substr($src, $i, 1);
+                if ($c eq '\\') { $i += 2; next; }
+                $i++;
+                last if $c eq '"';
+            }
+            next;
+        }
+        # single-quoted rune
+        if (substr($src, $i, 1) eq "'") {
+            $out .= ' ';
+            $i++;
+            while ($i < $len) {
+                my $c = substr($src, $i, 1);
+                if ($c eq '\\') { $i += 2; next; }
+                $i++;
+                last if $c eq "'";
+            }
+            next;
+        }
+        $out .= substr($src, $i, 1);
+        $i++;
+    }
+    return $out;
+}
+
+sub dir_to_import {
+    my ($dir) = @_;
+    my $rel = $dir;
+    $rel =~ s|^$REPO/||;
+    return "$MODULE/$rel";
+}
+
+sub make_sym_id {
+    my ($import_path, $recv, $name) = @_;
+    $recv //= '';
+    return "$import_path|$recv|$name";
+}
+
+sub parse_imports {
+    my ($src, $file) = @_;
+    my %imports;
+    my $pkg = '';
+    if ($src =~ /\bpackage\s+(\w+)/) {
+        $pkg = $1;
+    }
+    $file_pkg{$file} = $pkg;
+    while ($src =~ /\bimport\s+(?:\(\s*([\s\S]*?)\s*\)|"([^"]+)"|'([^']+)')/g) {
+        my $block = $1 // $2 // $3;
+        next unless defined $block;
+        if (!defined $1) {
+            my $path = $block;
+            my $local = (split m{/}, $path)[-1];
+            $local =~ s/-.*//;
