#!/usr/bin/perl
use strict;
use warnings;
use File::Find;
use File::Basename;

my $REPO = '/bench/repo';
my $MODULE = 'github.com/usememos/memos';

# sym_id = "import_path|recv|name"  recv empty for package funcs, *Type for pointer recv
my (%internal_decls, %all_decls);
my (%fanin, %fanin_test);          # sym_id -> { caller_id => 1 }
my (%file_pkg, %file_imports, %file_is_test);
my (@all_go_files);

sub read_file {
    my ($path) = @_;
    open my $fh, '<', $path or die "Cannot read $path: $!";
    local $/;
    my $content = <$fh>;
    close $fh;
    return $content;
}

sub strip_go_source {
    my ($src) = @_;
    my $out = '';
    my $i = 0;
    my $len = length($src);
    while ($i < $len) {
        # line comment
        if (substr($src, $i, 2) eq '//') {
            while ($i < $len && substr($src, $i, 1) ne "\n") { $i++; }
            next;
        }
        # block comment
        if (substr($src, $i, 2) eq '/*') {
            $i += 2;
            while ($i < $len - 1 && substr($src, $i, 2) ne '*/') { $i++; }
            $i += 2 if $i < $len;
            next;
        }
        # raw string
        if (substr($src, $i, 1) eq '`') {
            $out .= ' ';
            $i++;
            while ($i < $len && substr($src, $i, 1) ne '`') { $i++; }
            $i++ if $i < $len;
            next;
        }
        # double-quoted string
        if (substr($src, $i, 1) eq '"') {
            $out .= ' ';
            $i++;
            while ($i < $len) {
                my $c = substr($src, $i, 1);
                if ($c eq '\\') { $i += 2; next; }
                $i++;
                last if $c eq '"';
            }
            next;
        }
        # single-quoted rune
        if (substr($src, $i, 1) eq "'") {
            $out .= ' ';
            $i++;
            while ($i < $len) {
                my $c = substr($src, $i, 1);
                if ($c eq '\\') { $i += 2; next; }
                $i++;
                last if $c eq "'";
            }
            next;
        }
        $out .= substr($src, $i, 1);
        $i++;
    }
    return $out;
}

sub dir_to_import {
    my ($dir) = @_;
    my $rel = $dir;
    $rel =~ s|^$REPO/||;
    return "$MODULE/$rel";
}

sub make_sym_id {
    my ($import_path, $recv, $name) = @_;
    $recv //= '';
    return "$import_path|$recv|$name";
}

sub parse_imports {
    my ($src, $file) = @_;
    my %imports;
    my $pkg = '';
    if ($src =~ /\bpackage\s+(\w+)/) {
        $pkg = $1;
    }
    $file_pkg{$file} = $pkg;
    while ($src =~ /\bimport\s+(?:\(\s*([\s\S]*?)\s*\)|"([^"]+)"|'([^']+)')/g) {
        my $block = $1 // $2 // $3;
        next unless defined $block;
        if (!defined $1) {
            my $path = $block;
            my $local = (split m{/}, $path)[-1];
            $local =~ s/-.*//;
            $imports{$local} = $path;
            next;
        }
        while ($block =~ /(?:(\w+)\s+)?"([^"]+)"|'([^']+)'/g) {
            my ($alias, $path) = ($1, $2 // $3);
            $path =~ s/\s+$//;
            unless ($alias) {
                $alias = (split m{/}, $path)[-1];
                $alias =~ s/-.*//;
            }
            $imports{$alias} = $path;
        }
    }
    $file_imports{$file} = \%imports;
    return $pkg;
}

sub parse_func_decls {
    my ($src, $file, $import_path, $is_internal) = @_;
    my @funcs;
    my $pos = 0;
    while ($src =~ /\bfunc\b/g) {
        my $start = pos($src) - 4;
        my $rest = substr($src, $start);
        next unless $rest =~ /^func\s+(?:(\([^)]*\)\s*)?(\w+)\s*\(|(\([^)]*\)\s*)?\()/s;
        my $header_len = length($&);
        my $header = $&;
        my ($recv, $name);
        if ($header =~ /^func\s+\(([^)]*)\)\s*(\w+)\s*\(/) {
            my $recv_spec = $1;
            $name = $2;
            if ($recv_spec =~ /\*\s*([\w.]+)/) {
                $recv = "*$1";
            } elsif ($recv_spec =~ /([\w.]+)\s*$/) {
                $recv = $1;
            }
        } elsif ($header =~ /^func\s+(\w+)\s*\(/) {
            $name = $1;
        } else {
            # anonymous func
            $pos = $start + 4;
            next;
        }
        # find opening brace
        my $body_start = $start + $header_len;
        while ($body_start < length($src) && substr($src, $body_start, 1) !~ /[{]/) {
            $body_start++;
        }
        next if $body_start >= length($src);
        my $depth = 0;
        my $j = $body_start;
        for (; $j < length($src); $j++) {
            my $c = substr($src, $j, 1);
            if ($c eq '{') { $depth++; }
            elsif ($c eq '}') {
                $depth--;
                last if $depth == 0;
            }
        }
        my $body = substr($src, $body_start + 1, $j - $body_start - 1);
        my $caller_id = make_sym_id($import_path, $recv // '', $name);
        my $info = {
            file => $file,
            import_path => $import_path,
            recv => $recv // '',
            name => $name,
            id => $caller_id,
            body => $body,
            header => substr($src, $start, $j - $start + 1),
        };
        push @funcs, $info;
        $all_decls{$caller_id} = $info;
        if ($is_internal) {
            $internal_decls{$caller_id} = $info;
        }
        pos($src) = $j + 1;
    }
    return @funcs;
}

sub import_path_for_pkg_name {
    my ($pkg_name) = @_;
    # scan all files for package declarations matching name under repo
    for my $f (@all_go_files) {
        next if $file_is_test{$f};
        next unless ($file_pkg{$f} // '') eq $pkg_name;
        my $dir = dirname($f);
        return dir_to_import($dir);
    }
    return undef;
}

sub resolve_type_to_import {
    my ($type_expr) = @_;
    return undef unless defined $type_expr;
    $type_expr =~ s/^\*//;
    if ($type_expr =~ /^([\w]+)\.([\w]+)$/) {
        my ($pkg, $type) = ($1, $2);
        for my $f (@all_go_files) {
            next unless ($file_pkg{$f} // '') eq $pkg;
            return (dir_to_import(dirname($f)), "*$type");
        }
    }
    return (undef, $type_expr);
}

sub infer_var_types {
    my ($header, $body, $imports, $local_import) = @_;
    my %types;    # var -> {import_path, recv, name/type}
    my $combined = "$header\n$body";

    # receiver
    if ($header =~ /func\s+\((\w+)\s+\*?([\w.]+)\)/) {
        my ($v, $t) = ($1, $2);
        my ($ip, $rt) = resolve_type_to_import($t);
        $ip //= $local_import;
        $types{$v} = { import_path => $ip, recv => ($t =~ /^\*/ ? $t : "*$t"), kind => 'recv' };
        if ($t !~ /\./) {
            $types{$v} = { import_path => $local_import, recv => ($header =~ /\*\s*\Q$t\E/ ? "*$t" : $t), kind => 'recv' };
        }
    }

    # params: func(x *pkg.Type, y Type)
    while ($combined =~ /(?:func\s+\([^)]*\)\s*\w+\s*\(|func\s+\w+\s*\()([^)]*)\)/s) {
        my $params = $1;
        for my $p (split /,/, $params) {
            $p =~ s/^\s+|\s+$//g;
            next if $p eq '' || $p eq '...';
            if ($p =~ /(\w+)\s+\*?([\w.\[\]]+)/) {
                my ($v, $t) = ($1, $2);
                $t =~ s/\[\].*$//;
                if ($t =~ /^([\w]+)\.([\w]+)$/) {
                    my $pkg = $1;
                    if (my $ip = $imports->{$pkg}) {
                        $types{$v} = { import_path => $ip, recv => "*$2", kind => 'param' };
                    }
                } else {
                    $types{$v} = { import_path => $local_import, recv => ($p =~ /\*\s*\Q$t\E/ ? "*$t" : $t), kind => 'param' };
                }
            }
        }
    }

    # var x *Type / var x Type
    while ($combined =~ /\bvar\s+(\w+)\s+\*?([\w.]+)/g) {
        my ($v, $t) = ($1, $2);
        if ($t =~ /^([\w]+)\.([\w]+)$/) {
            if (my $ip = $imports->{$1}) {
                $types{$v} = { import_path => $ip, recv => "*$2", kind => 'var' };
            }
        } else {
            $types{$v} = { import_path => $local_import, recv => ($combined =~ /\bvar\s+\Q$v\E\s+\*\s*\Q$t\E/ ? "*$t" : $t), kind => 'var' };
        }
    }

    # x := pkg.Func() / x, err := pkg.Func()
    while ($combined =~ /\b(\w+)\s*,?\s*(?:\w+\s*)?:=\s*([\w.]+)\.(\w+)\s*\(/g) {
        my ($v, $pkg, $fn) = ($1, $2, $3);
        my $ip = $imports->{$pkg} // ($pkg eq ($file_pkg{$local_import} // '') ? $local_import : undef);
        $ip = $imports->{$pkg} if exists $imports->{$pkg};
        if ($ip) {
            my $ret = return_type_of($ip, '', $fn);
            $types{$v} = $ret if $ret;
        }
    }

    # x := Func() unqualified in same package
    while ($combined =~ /\b(\w+)\s*,?\s*(?:\w+\s*)?:=\s*(\w+)\s*\(/g) {
        my ($v, $fn) = ($1, $2);
        next if $fn =~ /^(make|new|len|cap|append|delete|close|panic|recover|print|println)$/;
        my $ret = return_type_of($local_import, '', $fn);
        $types{$v} = $ret if $ret;
    }

    # typed short decl: engine *filter.Engine
    while ($combined =~ /\b(\w+)\s+\*?([\w.]+)\s*:?=/) {
        # skip, mostly covered
    }

    return \%types;
}

sub return_type_of {
    my ($import_path, $recv, $name) = @_;
    for my $id (keys %all_decls) {
        my $d = $all_decls{$id};
        next unless $d->{import_path} eq $import_path && $d->{name} eq $name;
        next if $recv && ($d->{recv} // '') ne $recv;
        my $h = $d->{header};
        if ($h =~ /\)\s*\*?([\w.\[\]]+)\s*\{/) {
            my $t = $1;
            $t =~ s/\[\].*$//;
            if ($t =~ /^([\w]+)\.([\w]+)$/) {
                my $pkg = $1;
                for my $f (@all_go_files) {
                    if (($file_pkg{$f}//'') eq $pkg) {
                        return { import_path => dir_to_import(dirname($f)), recv => "*$2", kind => 'ret' };
                    }
                }
            }
            return { import_path => $import_path, recv => ($h =~ /\)\s*\*\s*\Q$t\E/ ? "*$t" : $t), kind => 'ret' };
        }
        if ($h =~ /\)\s*\(([^)]*)\)/) {
            my $rets = $1;
            if ($rets =~ /\*?([\w.]+)/) {
                my $t = $1;
                if ($t =~ /^([\w]+)\.([\w]+)$/) {
                    for my $f (@all_go_files) {
                        if (($file_pkg{$f}//'') eq $1) {
                            return { import_path => dir_to_import(dirname($f)), recv => "*$2", kind => 'ret' };
                        }
                    }
                }
                return { import_path => $import_path, recv => ($rets =~ /\*\s*\Q$t\E/ ? "*$t" : $t), kind => 'ret' };
            }
        }
    }
    return undef;
}

sub resolve_call {
    my ($pkg_or_var, $method, $imports, $local_import, $var_types) = @_;
    my @candidates;

    # Qualified package call: filter.DefaultEngine
    if (exists $imports->{$pkg_or_var}) {
        my $ip = $imports->{$pkg_or_var};
        push @candidates, make_sym_id($ip, '', $method);
        # also method on type named like package? uncommon
        return @candidates if $ip =~ m{/internal/};
        return @candidates if $ip =~ m{^github.com/usememos/memos/internal/};
    }

    # Same-package unqualified function
    if (!exists $imports->{$pkg_or_var}) {
        push @candidates, make_sym_id($local_import, '', $method) if $pkg_or_var eq ($file_pkg{$local_import} // '');

        # Method call on variable
        if (my $vt = $var_types->{$pkg_or_var}) {
            my $ip = $vt->{import_path};
            my $recv = $vt->{recv};
            $recv = "*$recv" if $recv && $recv !~ /^\*/ && $method =~ /^[A-Z]/;
            push @candidates, make_sym_id($ip, $recv, $method);
            # try normalized recv forms
            my $bare = $recv;
            $bare =~ s/^\*//;
            push @candidates, make_sym_id($ip, "*$bare", $method);
            push @candidates, make_sym_id($ip, $bare, $method);
        }

        # Local package method when var matches common receiver names - use enclosing type from caller
        push @candidates, make_sym_id($local_import, '', $method);
    }

    return @candidates;
}

sub record_fanin {
    my ($caller, $callee, $is_test) = @_;
    return unless exists $internal_decls{$callee};
    if ($is_test) {
        $fanin_test{$callee}{$caller} = 1;
    } else {
        $fanin{$callee}{$caller} = 1;
    }
}

# --- main ---

find({
    wanted => sub {
        return unless /\.go$/;
        push @all_go_files, $File::Find::name;
        $file_is_test{$File::Find::name} = ($File::Find::name =~ /_test\.go$/);
    },
    no_chdir => 1,
}, $REPO);

@all_go_files = sort @all_go_files;

# Pass 1: packages, imports, declarations
my (@internal_funcs, @all_funcs);
for my $file (@all_go_files) {
    my $raw = read_file($file);
    my $src = strip_go_source($raw);
    parse_imports($src, $file);
    my $dir = dirname($file);
    my $import_path = dir_to_import($dir);
    my $is_internal = ($file =~ m{$REPO/internal/});
    my @funcs = parse_func_decls($src, $file, $import_path, $is_internal);
    push @all_funcs, @funcs;
    push @internal_funcs, grep { $is_internal } @funcs;
}

# Build lookup for decl existence with recv normalization
my %decl_lookup;
for my $id (keys %internal_decls) {
    my ($ip, $recv, $name) = split /\|/, $id, 3;
    $decl_lookup{"$ip|$name"}->{$recv} = $id;
    my $bare = $recv;
    $bare =~ s/^\*//;
    $decl_lookup{"$ip|*$bare|$name"} = $id;
}

sub normalize_callee {
    my ($cand) = @_;
    return $cand if exists $internal_decls{$cand};
    my ($ip, $recv, $name) = split /\|/, $cand, 3;
    if (exists $decl_lookup{"$ip|$name"}) {
        my $h = $decl_lookup{"$ip|$name"};
        if (ref $h eq 'HASH') {
            for my $r (keys %$h) {
                return $h->{$r} if exists $internal_decls{$h->{$r}};
            }
        }
    }
    my $bare = $recv // '';
    $bare =~ s/^\*//;
    for my $try ("$ip|*$bare|$name", "$ip|$bare|$name", "$ip||$name") {
        return $try if exists $internal_decls{$try};
    }
    return undef;
}

# Pass 2: extract calls
for my $func (@all_funcs) {
    my $file = $func->{file};
    my $imports = $file_imports{$file};
    my $local_import = $func->{import_path};
    my $is_test = $file_is_test{$file};
    my $var_types = infer_var_types($func->{header}, $func->{body}, $imports, $local_import);
    my $body = $func->{body};
    my $caller = $func->{id};

    # selector calls: a.b(
    while ($body =~ /\b([A-Za-z_][A-Za-z0-9_]*)\.([A-Za-z_][A-Za-z0-9_]*)\s*\(/g) {
        my ($a, $b) = ($1, $2);
        next if $a eq 'http' || $a eq 'json' || $a eq 'fmt' || $a eq 'strings' || $a eq 'strconv';
        next if $a eq 'context' || $a eq 'time' || $a eq 'errors' || $a eq 'log' || $a eq 'slog';
        next if $a eq 'sql' || $a eq 'os' || $a eq 'filepath' || $a eq 'regexp' || $a eq 'bytes';
        next if $a eq 'io' || $a eq 'net' || $a eq 'url' || $a eq 'mime' || $a eq 'template';
        next if $a eq 'sync' || $a eq 'atomic' || $a eq 'reflect' || $a eq 'sort' || $a eq 'math';
        next if $a eq 'crypto' || $a eq 'encoding' || $a eq 'unicode' || $a eq 'runtime';
        next if $b eq 'Errorf' || $b eq 'Sprintf' || $b eq 'Wrapf' || $b eq 'Wrap';
        my @cands = resolve_call($a, $b, $imports, $local_import, $var_types);
        for my $c (@cands) {
            my $n = normalize_callee($c);
            record_fanin($caller, $n, $is_test) if $n;
        }
    }

    # unqualified calls: Foo(
    while ($body =~ /(?:^|[^\w.])([A-Z][A-Za-z0-9_]*)\s*\(/gm) {
        my ($fn) = ($1);
        next if $fn =~ /^(Make|New|Append|Delete|Close|Panic|Recover|Print|Println|Len|Cap|Copy|Complex|Real|Imag)$/;
        my $cand = make_sym_id($local_import, '', $fn);
        my $n = normalize_callee($cand);
        record_fanin($caller, $n, $is_test) if $n;
        # also try imported packages exposing this name (unlikely for uppercase)
        for my $alias (keys %$imports) {
            my $ip = $imports->{$alias};
            next unless $ip =~ m{/internal/};
            my $c2 = make_sym_id($ip, '', $fn);
            my $n2 = normalize_callee($c2);
            record_fanin($caller, $n2, $is_test) if $n2;
        }
    }
}

# Aggregate counts
my @ranked;
for my $id (keys %internal_decls) {
    my $prod = scalar keys %{$fanin{$id} // {}};
    my $test = scalar keys %{$fanin_test{$id} // {}};
    my $total = scalar keys %{ { %{$fanin{$id}//{}}, %{$fanin_test{$id}//{}} } };
    push @ranked, {
        id => $id,
        decl => $internal_decls{$id},
        prod => $prod,
        test => $test,
        total => $total,
        prod_callers => [sort keys %{$fanin{$id} // {}}],
        all_callers => [sort keys %{ { %{$fanin{$id}//{}}, %{$fanin_test{$id}//{}} } }],
    };
}

@ranked = sort { $b->{prod} <=> $a->{prod} || $b->{total} <=> $a->{total} || $a->{id} cmp $b->{id} } @ranked;

print "=== TOP 25 BY PRODUCTION FAN-IN (distinct caller funcs, non-test files) ===\n";
for my $i (0 .. 24) {
    last unless $ranked[$i];
    my $r = $ranked[$i];
    my $d = $r->{decl};
    my $sym = $d->{recv} ? "($d->{recv}).$d->{name}" : $d->{name};
    printf "%2d. prod=%3d test=%2d total=%3d  %s  %s\n", $i+1, $r->{prod}, $r->{test}, $r->{total}, $sym, $d->{file};
}

print "\n=== TOP 10 WITH CALLER DETAILS ===\n";
for my $i (0 .. 9) {
    last unless $ranked[$i];
    my $r = $ranked[$i];
    my $d = $r->{decl};
    my $sym = $d->{recv} ? "($d->{recv}).$d->{name}" : $d->{name};
    print "\n#$i+1 $sym @ $d->{file}\n";
    print "  prod callers ($r->{prod}):\n";
    for my $c (@{$r->{prod_callers}}[0..9]) {
        my $cd = $all_decls{$c};
        print "    - $c ($cd->{file})\n" if $cd;
    }
    print "    ...\n" if $r->{prod} > 10;
}

print "\n=== INTERNAL DECL COUNT: ", scalar(keys %internal_decls), " ===\n";
print "=== TOTAL NON-TEST GO FILES ANALYZED: ", scalar(grep { !$file_is_test{$_} } @all_go_files), " ===\n";

