    my ($a, $b, $imports, $local_ip, $types) = @_;
    my @out;
    if (exists $imports->{$a}) {
        push @out, sym_id($imports->{$a}, '', $b);
        return @out;
    }
    if (my $vt = $types->{$a}) {
        push @out, sym_id($vt->{ip}, $vt->{recv}, $b);
        my $bare = $vt->{recv}; $bare =~ s/^\*//;
        push @out, sym_id($vt->{ip}, "*$bare", $b);
        push @out, sym_id($vt->{ip}, $bare, $b);
    }
    push @out, sym_id($local_ip, '', $b);
    return @out;
}

sub normalize {
    my ($c) = @_;
    return $c if exists $internal_decls{$c};
    my ($ip,$r,$n) = split /\|/, $c, 3;
    for my $try ("$ip|*$r|$n", "$ip||$n") {
        my $b = $r; $b =~ s/^\*//;
        for ("$ip|*$b|$n", "$ip|$b|$n") { return $_ if exists $internal_decls{$_}; }
    }
    return undef;
}

sub record {
    my ($caller, $callee, $test) = @_;
    return unless $callee && exists $internal_decls{$callee};
    if ($test) { $fanin_test{$callee}{$caller}=1; } else { $fanin{$callee}{$caller}=1; }
}

