my $REPO = '/bench/repo';
my $MODULE = 'github.com/usememos/memos';

my (%internal_decls, %all_decls, %fanin, %fanin_test);
my (%file_pkg, %file_imports, %file_is_test, @all_go_files);

sub read_file {
    my ($path) = @_;
    open my $fh, '<', $path or die "Cannot read $path: $!";
    local $/; my $c = <$fh>; close $fh; return $c;
}

sub strip_go_source {
    my ($src) = @_;
    my ($out, $i, $len) = ('', 0, length($src));
    while ($i < $len) {
        if (substr($src,$i,2) eq '//') { while ($i<$len && substr($src,$i,1) ne "\n"){$i++;} next; }
        if (substr($src,$i,2) eq '/*') { $i+=2; while($i<$len-1 && substr($src,$i,2) ne '*/'){$i++;} $i+=2 if $i<$len; next; }
        if (substr($src,$i,1) eq '`') { $out.=' '; $i++; while($i<$len && substr($src,$i,1) ne '`'){$i++;} $i++ if $i<$len; next; }
        if (substr($src,$i,1) eq '"') { $out.=' '; $i++; while($i<$len){ my $c=substr($src,$i,1); if($c eq '\\'){$i+=2;next;} $i++; last if $c eq '"'; } next; }
        if (substr($src,$i,1) eq "'") { $out.=' '; $i++; while($i<$len){ my $c=substr($src,$i,1); if($c eq '\\'){$i+=2;next;} $i++; last if $c eq "'"; } next; }
        $out .= substr($src,$i,1); $i++;
    }
    return $out;
}

sub dir_to_import { my ($d)=@_; $d=~s|^$REPO/||; return "$MODULE/$d"; }
sub sym_id { my ($ip,$r,$n)=@_; return "$ip|".($r//'' )."|$n"; }

sub parse_imports {
    my ($src, $file) = @_;
    my ($pkg) = $src =~ /\bpackage\s+(\w+)/;
    $file_pkg{$file} = $pkg // '';
    my %imp;
    while ($src =~ /\bimport\s+(?:\(\s*([\s\S]*?)\s*\)|"([^"]+)")/g) {
        my $block = $1 // $2;
        if (defined $2) {
            my $local = (split m{/}, $2)[-1]; $local =~ s/-.*//; $imp{$local} = $2; next;
        }
        while ($block =~ /(?:(\w+)\s+)?"([^"]+)"/g) {
            my ($a,$p)=($1,$2); unless($a){$a=(split m{/},$p)[-1]; $a=~s/-.*//;}
            $imp{$a}=$p;
        }
    }
    $file_imports{$file}=\%imp;
}

sub find_matching_brace {
    my ($src, $start) = @_;
    my $depth = 0;
    for (my $j = $start; $j < length($src); $j++) {
        my $c = substr($src, $j, 1);
        if ($c eq '{') { $depth++; }
        elsif ($c eq '}') { $depth--; return $j if $depth == 0; }
    }
    return length($src)-1;
}

sub extract_functions {
    my ($src, $file, $import_path, $is_internal) = @_;
    my @funcs;
    my $offset = 0;
    while ($offset < length($src)) {
        my $idx = index($src, 'func', $offset);
        last if $idx < 0;
        # word boundary check
        if ($idx > 0 && substr($src,$idx-1,1) =~ /[\w]/) { $offset = $idx + 4; next; }
        my $rest = substr($src, $idx);
        my ($recv, $name);
        if ($rest =~ /^func\s+\(([^)]*)\)\s*(\w+)\s*\(/) {
            my $rs = $1; $name = $2;
            if ($rs =~ /\*\s*([\w.]+)/) { $recv = "*$1"; }
            elsif ($rs =~ /([\w.]+)\s*$/) { $recv = $1; }
        } elsif ($rest =~ /^func\s+(\w+)\s*\(/) {
            $name = $1;
        } else { $offset = $idx + 4; next; }

        my $hdr_end = $idx + length($rest =~ /^func\s+(?:\([^)]*\)\s*)?\w+\s*\([^)]*\)(?:\s*\([^)]*\))?\s*\{/ ? $& : '');
        # simpler: scan to first {
        my $p = $idx + 4;
        while ($p < length($src) && substr($src,$p,1) ne '{') { $p++; }
        my $body_end = find_matching_brace($src, $p);
        my $body = substr($src, $p+1, $body_end - $p - 1);
        my $header = substr($src, $idx, $body_end - $idx + 1);
        my $id = sym_id($import_path, $recv // '', $name);
        my $info = { file=>$file, import_path=>$import_path, recv=>$recv//'', name=>$name, id=>$id, body=>$body, header=>$header };
        push @funcs, $info;
        $all_decls{$id} = $info;
        $internal_decls{$id} = $info if $is_internal;
        $offset = $body_end + 1;
    }
    return @funcs;
}

my %stdlib = map { $_=>1 } qw(fmt strings strconv context time errors log slog sql os filepath regexp bytes io net url mime template sync atomic reflect sort math crypto encoding unicode runtime http json sync atomic testing);

sub infer_types {
    my ($header, $body, $imports, $local_ip) = @_;
    my %t;
    my $c = "$header\n$body";
    if ($header =~ /func\s+\((\w+)\s+(\*?)([\w.]+)\)/) {
        my ($v,$ptr,$ty)=($1,$2,$3);
        $t{$v} = { ip=>$local_ip, recv=>($ptr?"*$ty":$ty) };
    }
    while ($c =~ /\b(\w+)\s*,?\s*(?:\w+\s*)?:=\s*([\w.]+)\.(\w+)\s*\(/g) {
        my ($v,$pkg,$fn)=($1,$2,$3);
        next unless exists $imports->{$pkg};
        my $ip = $imports->{$pkg};
        for my $did (keys %all_decls) {
            my $d = $all_decls{$did};
            next unless $d->{import_path} eq $ip && $d->{name} eq $fn && !$d->{recv};
            if ($d->{header} =~ /\)\s*(\*?[\w.]+)/) {
                my $rt = $1; $rt =~ s/\[\].*//;
                $rt = "*$rt" if $rt !~ /^\*/ && $d->{header} =~ /\)\s*\*\s*\Q$rt\E/;
                $t{$v} = { ip=>$ip, recv=>$rt };
            }
        }
    }
    while ($c =~ /\b(\w+)\s+\*?([\w.]+)\s*,?\s*$/gm) {} # skip
    while ($c =~ /\b(\w+)\s+\*?([\w.]+)\s*[,)]/g) {
        my ($v,$ty)=($1,$2); next if $ty =~ /^(int|string|bool|error|any|interface|context|Context|byte|rune|float|struct|map|chan)$/;
        if ($ty =~ /^([\w]+)\.([\w]+)$/) {
            next unless exists $imports->{$1};
            $t{$v} = { ip=>$imports->{$1}, recv=>"*".$2 };
        } else {
            $t{$v} = { ip=>$local_ip, recv=>($c =~ /\b\Q$v\E\s+\*\s*\Q$ty\E/ ? "*$ty" : $ty) };
        }
    }
    return \%t;
}

sub resolve_callee {
    my ($a, $b, $imports, $local_ip, $types) = @_;
    my @out;
    if (exists $imports->{$a}) {
        push @out, sym_id($imports->{$a}, '', $b);
        return @out;
    }
    if (my $vt = $types->{$a}) {
        push @out, sym_id($vt->{ip}, $vt->{recv}, $b);
        my $bare = $vt->{recv}; $bare =~ s/^\*//;
        push @out, sym_id($vt->{ip}, "*$bare", $b);
        push @out, sym_id($vt->{ip}, $bare, $b);
    }
    push @out, sym_id($local_ip, '', $b);
    return @out;
}

sub normalize {
    my ($c) = @_;
    return $c if exists $internal_decls{$c};
    my ($ip,$r,$n) = split /\|/, $c, 3;
    for my $try ("$ip|*$r|$n", "$ip||$n") {
        my $b = $r; $b =~ s/^\*//;
        for ("$ip|*$b|$n", "$ip|$b|$n") { return $_ if exists $internal_decls{$_}; }
    }
    return undef;
}

sub record {
    my ($caller, $callee, $test) = @_;
    return unless $callee && exists $internal_decls{$callee};
    if ($test) { $fanin_test{$callee}{$caller}=1; } else { $fanin{$callee}{$caller}=1; }
}

open my $ff, '-|', 'find', $REPO, '-name', '*.go', '-type', 'f' or die $!;
while (<$ff>) { chomp; push @all_go_files, $_; $file_is_test{$_} = /_test\.go$/; }
close $ff;

my @all_funcs;
for my $file (@all_go_files) {
    my $src = strip_go_source(read_file($file));
    parse_imports($src, $file);
    my $ip = dir_to_import(dirname($file));
    my $int = ($file =~ m{$REPO/internal/});
    push @all_funcs, extract_functions($src, $file, $ip, $int);
}

for my $func (@all_funcs) {
    my ($file, $body, $caller) = ($func->{file}, $func->{body}, $func->{id});
    my $imports = $file_imports{$file};
    my $local_ip = $func->{import_path};
    my $test = $file_is_test{$file};
    my $types = infer_types($func->{header}, $body, $imports, $local_ip);

    while ($body =~ /\b([A-Za-z_][A-Za-z0-9_]*)\.([A-Za-z_][A-Za-z0-9_]*)\s*\(/g) {
        my ($a,$b)=($1,$2);
        next if $stdlib{$a} || $a =~ /^(proto|pb|connect|echo|viper|cobra|uuid|testify)$/;
        for my $c (resolve_callee($a,$b,$imports,$local_ip,$types)) {
            record($caller, normalize($c), $test);
        }
    }
    while ($body =~ /(?:^|[^\w.])([A-Z][A-Za-z0-9_]*)\s*\(/gm) {
        my $fn = $1;
        record($caller, normalize(sym_id($local_ip,'',$fn)), $test);
        for my $alias (keys %$imports) {
            next unless $imports->{$alias} =~ m{/internal/};
            record($caller, normalize(sym_id($imports->{$alias},'',$fn)), $test);
        }
    }
}

my @ranked;
for my $id (keys %internal_decls) {
    my $prod = scalar keys %{$fanin{$id}//{}};
    my $test = scalar keys %{$fanin_test{$id}//{}};
    my %all = (%{$fanin{$id}//{}}, %{$fanin_test{$id}//{}});
    push @ranked, { id=>$id, d=>$internal_decls{$id}, prod=>$prod, test=>$test, total=>scalar keys %all,
        callers=>[sort keys %{$fanin{$id}//{}}] };
}
@ranked = sort { $b->{prod} <=> $a->{prod} || $b->{total} <=> $a->{total} } @ranked;

print "TOP 30 PRODUCTION FAN-IN\n";
for my $i (0..29) {
    last unless $ranked[$i];
    my $r = $ranked[$i]; my $d = $r->{d};
    my $sym = $d->{recv} ? "($d->{recv}).$d->{name}" : $d->{name};
    printf "%2d prod=%3d test=%2d total=%3d  %s\n    %s\n", $i+1,$r->{prod},$r->{test},$r->{total},$sym,$d->{file};
}

print "\nDETAIL TOP 5\n";
for my $i (0..4) {
    my $r = $ranked[$i]; my $d = $r->{d};
    my $sym = $d->{recv} ? "($d->{recv}).$d->{name}" : $d->{name};
    print "\n#$i+1 $sym prod=$r->{prod}\n";
    for my $c (@{$r->{callers}}) {
        my $cd = $all_decls{$c};
        print "  $c\n    -> $cd->{file}\n" if $cd;
    }
}

