                my $rt = $1; $rt =~ s/\[\].*//;
                $rt = "*$rt" if $rt !~ /^\*/ && $d->{header} =~ /\)\s*\*\s*\Q$rt\E/;
                $t{$v} = { ip=>$ip, recv=>$rt };
            } elsif ($d->{header} =~ /\)\s*\([^)]*\*?([\w.]+)/) {
                my $rt = $1; $rt =~ s/\[\].*//;
                $t{$v} = { ip=>$ip, recv=>"*".$rt };
            }
        }
    }
    while ($c =~ /\b(\w+)\s+\*?([\w.]+)\s*[,)]/g) {
        my ($v,$ty)=($1,$2);
        next if $ty =~ /^(int|string|bool|error|any|interface|Context|context|byte|rune|float64|float32|int32|int64|uint|uint32|uint64|struct|map|chan|FindMemo|FindAttachment|Memo|Attachment|DB|Profile|Engine|Service|Client|Store|T|B)$/i;
        if ($ty =~ /^([\w]+)\.([\w]+)$/) {
            next unless exists $imports->{$1};
            $t{$v} = { ip=>$imports->{$1}, recv=>"*".$2 };
        } elsif ($ty !~ /\./) {
            $t{$v} = { ip=>$local_ip, recv=>($c =~ /\b\Q$v\E\s+\*\s*\Q$ty\E/ ? "*$ty" : $ty) };
        }
