                my $rt = $1; $rt =~ s/\[\].*//;
                $t{$v} = { ip=>$ip, recv=>"*".$rt };
            }
        }
    }
    while ($c =~ /\b(\w+)\s+\*?([\w.]+)\s*[,)]/g) {
        my ($v,$ty)=($1,$2);
        next if $ty =~ /^(int|string|bool|error|any|interface|Context|context|byte|rune|float64|float32|int32|int64|uint|uint32|uint64|struct|map|chan|T|B|DB|Engine|Service|Client|Store|Profile|FindMemo|FindAttachment|Memo|Attachment)$/i;
