    if (my $vt = $types->{$a}) {
        push @out, sym_id($vt->{ip}, $vt->{recv}, $b);
        my $bare = $vt->{recv}; $bare =~ s/^\*//;
        push @out, sym_id($vt->{ip}, "*$bare", $b);
