    local $/; my $c = <$fh>; close $fh; return $c;
}

sub strip_go_source {
    my ($src) = @_;
    my ($out, $i, $len) = ('', 0, length($src));
    while ($i < $len) {
        if (substr($src,$i,2) eq '//') { while ($i<$len && substr($src,$i,1) ne "\n"){$i++;} next; }
        if (substr($src,$i,2) eq '/*') { $i+=2; while($i<$len-1 && substr($src,$i,2) ne '*/'){$i++;} $i+=2 if $i<$len; next; }
        if (substr($src,$i,1) eq '`') { $out.=' '; $i++; while($i<$len && substr($src,$i,1) ne '`'){$i++;} $i++ if $i<$len; next; }
        if (substr($src,$i,1) eq '"') { $out.=' '; $i++; while($i<$len){ my $c=substr($src,$i,1); if($c eq '\\'){$i+=2;next;} $i++; last if $c eq '"'; } next; }
        if (substr($src,$i,1) eq "'") { $out.=' '; $i++; while($i<$len){ my $c=substr($src,$i,1); if($c eq '\\'){$i+=2;next;} $i++; last if $c eq "'"; } next; }
        $out .= substr($src,$i,1); $i++;
    }
    return $out;
}

sub dir_to_import { my ($d)=@_; $d=~s|^$REPO/||; return "$MODULE/$d"; }
sub sym_id { my ($ip,$r,$n)=@_; return "$ip|".($r//'' )."|$n"; }

sub parse_imports {
    my ($raw, $file) = @_;
    my ($pkg) = $raw =~ /\bpackage\s+(\w+)/;
    $file_pkg{$file} = $pkg // '';
    my %imp;
    while ($raw =~ /\bimport\s+(?:\(\s*([\s\S]*?)\s*\)|"([^"]+)")/g) {
        my $block = $1 // $2;
        if (defined $2) {
            my $local = (split m{/}, $2)[-1]; $local =~ s/-.*//; $imp{$local} = $2; next;
        }
        while ($block =~ /(?:(\w+)\s+)?"([^"]+)"/g) {
            my ($a,$p)=($1,$2);
            unless ($a) { $a = (split m{/}, $p)[-1]; $a =~ s/-.*//; }
            $imp{$a} = $p;
        }
    }
    $file_imports{$file} = \%imp;
}

sub find_matching_brace {
    my ($src, $start) = @_;
    my $depth = 0;
    for (my $j = $start; $j < length($src); $j++) {
        my $c = substr($src, $j, 1);
        if ($c eq '{') { $depth++; }
        elsif ($c eq '}') { $depth--; return $j if $depth == 0; }
    }
    return length($src)-1;
}

sub extract_functions {
    my ($src, $file, $import_path, $is_internal) = @_;
    my @funcs;
    my $offset = 0;
    while ($offset < length($src)) {
        my $idx = index($src, 'func', $offset);
        last if $idx < 0;
        if ($idx > 0 && substr($src,$idx-1,1) =~ /[\w]/) { $offset = $idx + 4; next; }
        my $rest = substr($src, $idx);
        my ($recv, $name);
        if ($rest =~ /^func\s+\(([^)]*)\)\s*(\w+)\s*\(/) {
            my $rs = $1; $name = $2;
            if ($rs =~ /\*\s*([\w.]+)/) { $recv = "*$1"; }
            elsif ($rs =~ /([\w.]+)\s*$/) { $recv = $1; }
        } elsif ($rest =~ /^func\s+(\w+)\s*\(/) {
            $name = $1;
        } else { $offset = $idx + 4; next; }

        my $p = $idx + 4;
        while ($p < length($src) && substr($src,$p,1) ne '{') { $p++; }
        my $body_end = find_matching_brace($src, $p);
        my $body = substr($src, $p+1, $body_end - $p - 1);
        my $header = substr($src, $idx, $body_end - $idx + 1);
        my $id = sym_id($import_path, $recv // '', $name);
        my $info = { file=>$file, import_path=>$import_path, recv=>$recv//'', name=>$name, id=>$id, body=>$body, header=>$header };
        push @funcs, $info;
        $all_decls{$id} = $info;
        $internal_decls{$id} = $info if $is_internal;
        $offset = $body_end + 1;
    }
    return @funcs;
}

my %skip_pkg = map { $_=>1 } qw(fmt strings strconv context time errors log slog sql os filepath regexp bytes io net url mime template sync atomic reflect sort math crypto encoding unicode runtime http json testing proto pb connect echo viper cobra uuid testify errors pkg protojson gast east storepb apiv1 store smtp openaisdk genai cel grpc httptest testing);

sub infer_types {
    my ($header, $body, $imports, $local_ip) = @_;
    my %t;
    my $c = "$header\n$body";
    if ($header =~ /func\s+\((\w+)\s+(\*?)([\w.]+)\)/) {
        my ($v,$ptr,$ty)=($1,$2,$3);
        $t{$v} = { ip=>$local_ip, recv=>($ptr?"*$ty":$ty) };
    }
    while ($c =~ /\b(\w+)\s*,?\s*(?:\w+\s*)?:=\s*([\w.]+)\.(\w+)\s*\(/g) {
        my ($v,$pkg,$fn)=($1,$2,$3);
        next unless exists $imports->{$pkg};
        my $ip = $imports->{$pkg};
        for my $did (keys %all_decls) {
            my $d = $all_decls{$did};
            next unless $d->{import_path} eq $ip && $d->{name} eq $fn && !$d->{recv};
            if ($d->{header} =~ /\)\s*(\*?[\w.]+)/) {
                my $rt = $1; $rt =~ s/\[\].*//;
                $rt = "*$rt" if $rt !~ /^\*/ && $d->{header} =~ /\)\s*\*\s*\Q$rt\E/;
                $t{$v} = { ip=>$ip, recv=>$rt };
            } elsif ($d->{header} =~ /\)\s*\([^)]*\*?([\w.]+)/) {
                my $rt = $1; $rt =~ s/\[\].*//;
                $t{$v} = { ip=>$ip, recv=>"*".$rt };
            }
        }
    }
    while ($c =~ /\b(\w+)\s+\*?([\w.]+)\s*[,)]/g) {
        my ($v,$ty)=($1,$2);
        next if $ty =~ /^(int|string|bool|error|any|interface|Context|context|byte|rune|float64|float32|int32|int64|uint|uint32|uint64|struct|map|chan|T|B|DB|Engine|Service|Client|Store|Profile|FindMemo|FindAttachment|Memo|Attachment)$/i;
        if ($ty =~ /^([\w]+)\.([\w]+)$/) {
            next unless exists $imports->{$1};
            $t{$v} = { ip=>$imports->{$1}, recv=>"*".$2 };
        } elsif ($ty !~ /\./) {
            $t{$v} = { ip=>$local_ip, recv=>($c =~ /\b\Q$v\E\s+\*\s*\Q$ty\E/ ? "*$ty" : $ty) };
        }
    }
    return \%t;
}

sub resolve_callee {
    my ($a, $b, $imports, $local_ip, $types) = @_;
    my @out;
    if (exists $imports->{$a}) {
        push @out, sym_id($imports->{$a}, '', $b);
        return @out;
    }
    if (my $vt = $types->{$a}) {
        push @out, sym_id($vt->{ip}, $vt->{recv}, $b);
        my $bare = $vt->{recv}; $bare =~ s/^\*//;
        push @out, sym_id($vt->{ip}, "*$bare", $b);
        push @out, sym_id($vt->{ip}, $bare, $b);
    }
    push @out, sym_id($local_ip, '', $b);
    return @out;
}

sub normalize {
    my ($c) = @_;
    return $c if exists $internal_decls{$c};
    my ($ip,$r,$n) = split /\|/, $c, 3;
    my $b = $r // ''; $b =~ s/^\*//;
    for my $try ("$ip|*$b|$n", "$ip|$b|$n", "$ip||$n") {
        return $try if exists $internal_decls{$try};
    }
    return undef;
}

sub record {
    my ($caller, $callee) = @_;
    return unless $callee && exists $internal_decls{$callee};
    $fanin_callers{$callee}{$caller} = 1;
    $callsite_count{$callee}++;
}

open my $ff, '-|', 'find', $REPO, '-name', '*.go', '-type', 'f' or die $!;
while (<$ff>) { chomp; push @all_go_files, $_; }
close $ff;

my @all_funcs;
for my $file (@all_go_files) {
    my $raw = read_file($file);
    parse_imports($raw, $file);
    my $src = strip_go_source($raw);
    my $ip = dir_to_import(dirname($file));
    my $int = ($file =~ m{$REPO/internal/});
    push @all_funcs, extract_functions($src, $file, $ip, $int);
}

for my $func (@all_funcs) {
    my ($file, $body, $caller) = ($func->{file}, $func->{body}, $func->{id});
    my $imports = $file_imports{$file};
    my $local_ip = $func->{import_path};
    my $types = infer_types($func->{header}, $body, $imports, $local_ip);

    while ($body =~ /\b([A-Za-z_][A-Za-z0-9_]*)\.([A-Za-z_][A-Za-z0-9_]*)\s*\(/g) {
        my ($a,$b)=($1,$2);
        next if $skip_pkg{$a};
        for my $c (resolve_callee($a,$b,$imports,$local_ip,$types)) {
            record($caller, normalize($c));
        }
    }
    while ($body =~ /(?:^|[^\w.])([A-Z][A-Za-z0-9_]*)\s*\(/gm) {
        my $fn = $1;
        record($caller, normalize(sym_id($local_ip,'',$fn)));
        for my $alias (keys %$imports) {
            next unless ($imports->{$alias} // '') =~ m{/internal/};
            record($caller, normalize(sym_id($imports->{$alias},'',$fn)));
        }
    }
}

sub fmt_sym {
    my ($d) = @_;
    return $d->{recv} ? "($d->{recv}).$d->{name}" : $d->{name};
}

my @ranked;
for my $id (keys %internal_decls) {
    my $d = $internal_decls{$id};
    push @ranked, {
        id => $id,
        d => $d,
        callers => scalar keys %{$fanin_callers{$id} // {}},
        sites => $callsite_count{$id} // 0,
        caller_list => [sort keys %{$fanin_callers{$id} // {}}],
    };
}

my @by_callers = sort { $b->{callers} <=> $a->{callers} || $b->{sites} <=> $a->{sites} || $a->{id} cmp $b->{id} } @ranked;
my @by_sites   = sort { $b->{sites} <=> $a->{sites} || $b->{callers} <=> $a->{callers} || $a->{id} cmp $b->{id} } @ranked;

print "=== (a) TOP 15 BY DISTINCT CALLER FUNCTIONS (all .go incl tests) ===\n";
for my $i (0..14) {
    my $r = $by_callers[$i]; my $d = $r->{d};
    printf "%2d. callers=%3d sites=%3d  %s\n    %s\n", $i+1, $r->{callers}, $r->{sites}, fmt_sym($d), $d->{file};
}

print "\n=== (b) TOP 15 BY RAW CALL SITES (all .go incl tests) ===\n";
for my $i (0..14) {
    my $r = $by_sites[$i]; my $d = $r->{d};
    printf "%2d. sites=%3d callers=%3d  %s\n    %s\n", $i+1, $r->{sites}, $r->{callers}, fmt_sym($d), $d->{file};
}

print "\n=== NewEngine DETAIL ===\n";
for my $id (keys %internal_decls) {
    next unless $internal_decls{$id}{name} eq 'NewEngine';
    my $d = $internal_decls{$id};
    my $r = { callers => scalar keys %{$fanin_callers{$id}//{}}, sites => $callsite_count{$id}//0, caller_list => [sort keys %{$fanin_callers{$id}//{}}] };
    print "symbol: ", fmt_sym($d), "\n";
    print "sym_id: $id\n";
    print "file: $d->{file}\n";
    print "import_path: $d->{import_path}\n";
    print "distinct_callers: $r->{callers}\n";
    print "raw_call_sites: $r->{sites}\n";
    print "callers:\n";
    for my $c (@{$r->{caller_list}}) {
        my $cd = $all_decls{$c};
        printf "  - %s (%s) in %s\n", fmt_sym($cd), $cd->{import_path}, $cd->{file} if $cd;
    }
}

print "\n=== addArg DETAIL ===\n";
for my $id (keys %internal_decls) {
    next unless $internal_decls{$id}{name} eq 'addArg';
    my $d = $internal_decls{$id};
    print "callers=", scalar(keys %{$fanin_callers{$id}//{}}), " sites=", ($callsite_count{$id}//0), "\n";
}

print "\ntotal_internal_decls=", scalar(keys %internal_decls), " total_go_files=", scalar(@all_go_files), "\n";

